#!/usr/bin/env python3
"""Read bytecode from hex files, JSON artifacts and generated bytecode files."""

from __future__ import annotations

import json
import re
import sys
from dataclasses import dataclass, field
from pathlib import Path


def recursively_find_bytecode(value: object) -> str | None:
    if isinstance(value, dict):
        for key in ("object", "bytecode", "deployedBytecode"):
            if key in value:
                found = recursively_find_bytecode(value[key])
                if found:
                    return found
        for child in value.values():
            found = recursively_find_bytecode(child)
            if found:
                return found
    elif isinstance(value, list):
        for child in value:
            found = recursively_find_bytecode(child)
            if found:
                return found
    elif isinstance(value, str) and re.fullmatch(r"(?:0x)?[0-9a-fA-F]+", value):
        return value
    return None


def parse_bytecode_text(text: str) -> bytes:
    """Hex (with or without `0x`, whitespace, commas), a JSON artifact holding hex, or one Lean
    `⟨#[…]⟩` byte-array literal."""
    stripped = text.strip()
    lean_array = re.search(r"⟨#\[(.*?)\]\s*⟩", stripped, flags=re.DOTALL)
    if lean_array:
        array_body = re.sub(r"--[^\n]*", "", lean_array.group(1))
        array_body = re.sub(r"/-(?:.|\n)*?-/", "", array_body)
        tokens = re.findall(r"0x[0-9a-fA-F]+|\b[0-9]+\b", array_body)
        values = [int(token, 0) for token in tokens]
        if not values or any(value > 255 for value in values):
            raise ValueError("Lean ByteArray literal must contain bytes in the range 0..255")
        return bytes(values)
    if stripped.startswith(("{", "[")):
        candidate = recursively_find_bytecode(json.loads(stripped))
        if candidate is None:
            raise ValueError("JSON contains no hex bytecode object")
        stripped = candidate
    stripped = re.sub(r"0x", "", stripped, flags=re.IGNORECASE)
    stripped = re.sub(r"[\s,_]", "", stripped)
    if not re.fullmatch(r"[0-9a-fA-F]*", stripped) or len(stripped) % 2:
        raise ValueError("bytecode must contain an even number of hexadecimal digits")
    return bytes.fromhex(stripped)


# --------------------------------------------------------------------------------------------
# Bytecode files (`Bytecode.lean` / `CreationBytecode.lean`) are written by `gen_bytecode.py`.
# See `Reasoning/Disassembly/Facts.lean` for their structure.  The patterns below read the
# bytecode literal and the names in the file back from its text.

BYTECODE_FILE_CONSTANT = re.compile(r"^def (\S+) : ByteArray := ⟨#\[([^\]]*)\]⟩", re.M)
BYTECODE_FILE_NAMESPACE = re.compile(r"^namespace (\S+\.(?:Creation)?Bytecode)\s*$", re.M)
BYTECODE_FILE_TREE = re.compile(r"^noncomputable def tree : EVM\.Disassembly\.Tree :=\s*eval%",
                                re.M)
BYTECODE_FILE_LAYOUT = re.compile(r"\(siteNumbers (\S+)\.sites names\)")
BYTECODE_FILE_NAMES = re.compile(r"^def names : List String := (\[[^\n]*\])\s*$", re.M)
BYTECODE_FILE_TAIL = re.compile(r"^theorem decodes_code \((\w+) : ByteArray\)", re.M)
BYTECODE_FILE_BLOCKS = re.compile(r"^theorem _root_\.(\S+)\.immutableTemplate_size\b", re.M)
BYTECODE_FILE_VALID_JUMPS = re.compile(r"^@\[valid_jumps\] theorem _root_\.(\S+)", re.M)
IMPORT = re.compile(r"^import\s+(\S+)", re.M)


def parse_bytes_literal(text: str) -> bytes:
    """The bytes in the body of a `⟨#[…]⟩` literal."""
    tokens = [t for t in re.split(r"[\s,]+", text) if t]
    out = []
    for token in tokens:
        if not re.fullmatch(r"0x[0-9a-fA-F]{1,2}", token):
            raise ValueError(f"not a byte literal: {token!r}")
        out.append(int(token, 16))
    return bytes(out)


@dataclass(frozen=True)
class BytecodeFile:
    """A parsed bytecode file.  ``code`` is the bytes of the literal, which has zeros at solc
    immutable sites.  ``layout`` is the full name of the layout constant and ``blocks`` the
    namespace of the layout facts."""
    namespace: str
    bytecode: str
    code: bytes = field(default=b"", repr=False)
    creation: bool = False
    followed_by: str | None = None
    layout: str | None = None
    names: tuple[str, ...] = ()
    blocks: str | None = None
    valid_jumps: str | None = None
    imports: tuple[str, ...] = ()
    path: Path | None = field(default=None, compare=False)

    @property
    def hex_name(self) -> str:
        """The hex file the bytes come from: `creation.hex` or `runtime.hex`."""
        return "creation.hex" if self.creation else "runtime.hex"

    @property
    def hex_path(self) -> Path:
        """`hex_name` in the bytecode file's directory."""
        if self.path is None:
            raise ValueError("a bytecode file parsed from text has no directory")
        return self.path.parent / self.hex_name


def parse_bytecode_file(text: str, path: Path | None = None) -> BytecodeFile | None:
    """Parse a bytecode file.  Returns ``None`` if ``text`` is not one and raises ``ValueError``
    if it is malformed."""
    if not BYTECODE_FILE_TREE.search(text):
        return None
    where = f"{path}: " if path else ""
    constant = BYTECODE_FILE_CONSTANT.search(text)
    if constant is None:
        raise ValueError(f"{where}bytecode file without a `def … : ByteArray := ⟨#[…]⟩` literal")
    namespace = BYTECODE_FILE_NAMESPACE.search(text)
    if namespace is None:
        raise ValueError(f"{where}bytecode file outside a `<M>.Bytecode` namespace")
    try:
        code = parse_bytes_literal(constant.group(2))
    except ValueError as error:
        raise ValueError(f"{where}{error}") from None
    layout = BYTECODE_FILE_LAYOUT.search(text)
    names = BYTECODE_FILE_NAMES.search(text)
    tail = BYTECODE_FILE_TAIL.search(text)
    blocks = BYTECODE_FILE_BLOCKS.search(text)
    valid_jumps = BYTECODE_FILE_VALID_JUMPS.search(text)
    if bool(layout) != bool(blocks):
        raise ValueError(f"{where}bytecode file: a layout without its facts, or the other way "
                         "round")
    return BytecodeFile(
        namespace=namespace.group(1), bytecode=constant.group(1), code=code,
        creation=namespace.group(1).endswith(".CreationBytecode"),
        followed_by=tail.group(1) if tail else None,
        layout=layout.group(1) if layout else None,
        names=tuple(json.loads(names.group(1))) if names else (),
        blocks=blocks.group(1) if blocks else None,
        valid_jumps=valid_jumps.group(1) if valid_jumps else None,
        imports=tuple(IMPORT.findall(text)), path=path)


def read_bytecode_file(path: Path) -> BytecodeFile | None:
    """The bytecode file at ``path``, or ``None`` if it does not exist or is not one."""
    if not path.is_file():
        return None
    return parse_bytecode_file(path.read_text(encoding="utf-8"), path)


def bytecode_file_namespace(text: str) -> str | None:
    """The namespace of the bytecode file ``text``, or ``None`` if it is not one."""
    found = parse_bytecode_file(text)
    return found.namespace if found else None


def is_bytecode_file(path: Path) -> bool:
    """Whether ``path`` is a bytecode file."""
    return read_bytecode_file(path) is not None


def bytecode_file_constants(text: str) -> list[str]:
    """The full names of the ByteArray constants the bytecode file defines."""
    found = parse_bytecode_file(text)
    return [found.bytecode] if found else []


def check_bytecode_hex(file: BytecodeFile, hex_path: Path | None = None,
                       sites: dict[int, str] | None = None) -> None:
    """Raise ``ValueError`` unless the bytes of the bytecode file are those of ``hex_path``
    (default: the hex file in its directory), with the immutable sites zeroed if the file has a
    layout.  ``sites`` defaults to `bytecode_file_sites`."""
    hex_path = hex_path or file.hex_path
    if not hex_path.is_file():
        raise ValueError(f"{file.path}: {hex_path} does not exist")
    actual = parse_bytecode_text(hex_path.read_text(encoding="utf-8"))
    if file.layout is not None:
        actual = zero_sites(actual, bytecode_file_sites(file, actual) if sites is None else sites,
                            file.path)
    if actual != file.code:
        first = next((k for k, (a, b) in enumerate(zip(actual, file.code)) if a != b),
                     min(len(actual), len(file.code)))
        raise ValueError(
            f"{file.path}: the bytes written in the bytecode file differ from {hex_path}"
            + (" (immutable sites zeroed)" if file.layout is not None else "")
            + f" ({len(file.code)} and {len(actual)} bytes, first difference at byte {first}); "
            "if the hex file holds the intended code, regenerate the bytecode file "
            "(scripts/gen_bytecode.py --force)")


def contract_code(directory: Path, creation: bool = False) -> bytes:
    """The runtime (or creation) bytes of a contract directory.  They are read from its hex file
    if there is one, otherwise from its bytecode file, which has zeros at solc immutable sites."""
    hex_path = directory / ("creation.hex" if creation else "runtime.hex")
    if hex_path.is_file():
        return parse_bytecode_text(hex_path.read_text(encoding="utf-8"))
    file = read_bytecode_file(directory / ("CreationBytecode.lean" if creation
                                           else "Bytecode.lean"))
    if file is None:
        raise ValueError(f"{directory}: neither {hex_path.name} nor a bytecode file")
    return file.code


def bytecode_file_sites(file: BytecodeFile, code: bytes) -> dict[int, str]:
    """Offset -> layout key of each immutable site of a bytecode file with a layout.  Taken from
    the build JSON next to the file if it lists immutables, otherwise read from the Lean layout
    (`generate_rd_blocks.read_lean_layout`, which needs its module built)."""
    if file.layout is None:
        return {}
    directory = file.hex_path.parent
    for build_path in sorted(directory.glob("*.build.json")):
        build = json.loads(build_path.read_text(encoding="utf-8"))
        if build.get("compiler", {}).get("kind") == "vyper" or not build.get("immutables"):
            continue
        return {off: imm["name"] for imm in build["immutables"] for off in imm["offsets"]}
    import generate_rd_blocks
    imports = [m for m in file.imports if not m.startswith("Reasoning.")]
    found = generate_rd_blocks.read_lean_layout(file.layout, imports, code)
    return {off: key for off, (_, key) in found.items()}


def zero_sites(code: bytes, sites: dict[int, str] | list[int], where: object = None) -> bytes:
    """``code`` with the 32 bytes at every immutable site set to zero."""
    out = bytearray(code)
    for off in sites:
        if not (1 <= off and off + 32 <= len(out)):
            raise ValueError(f"{where}: immutable site {off} outside the code")
        out[off:off + 32] = bytes(32)
    return bytes(out)


def bytecode_file_bytes(file: BytecodeFile) -> bytes:
    """The bytes of the literal of a bytecode file."""
    return file.code


def read_bytecode(path: Path, code_term: str | None = None) -> bytes:
    raw = sys.stdin.buffer.read() if str(path) == "-" else path.read_bytes()
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        return raw
    if code_term is not None and path.suffix == ".lean":
        # a bytecode file: read its literal
        file = parse_bytecode_file(text, path)
        if file is None:
            raise ValueError(f"{path} is not a bytecode file (scripts/gen_bytecode.py)")
        local = code_term.rsplit(".", 1)[-1]
        if file.bytecode.rsplit(".", 1)[-1] != local:
            raise ValueError(f"the bytecode file {path} does not define {code_term}")
        return file.code
    try:
        return parse_bytecode_text(text)
    except (ValueError, json.JSONDecodeError):
        return raw
